async getSlots(): Promise<ResourceSlotsDto[]> {
  const slots = await this.manager.find(Slot, {
    order: { start: 'ASC', id: 'ASC' },
  });

  const slotsByResource = new Map<number, Slot[]>();
  for (const slot of slots) {
    const resourceSlots = slotsByResource.get(slot.resourceId) ?? [];
    resourceSlots.push(slot);
    slotsByResource.set(slot.resourceId, resourceSlots);
  }

  const conflictMap = new Map<number, SlotDto[]>();
  for (const resourceSlots of slotsByResource.values()) {
    for (let slotIndex = 0; slotIndex < resourceSlots.length; slotIndex++) {
      const currentSlot = resourceSlots[slotIndex];

      for (
        let nextIndex = slotIndex + 1;
        nextIndex < resourceSlots.length;
        nextIndex++
      ) {
        const nextSlot = resourceSlots[nextIndex];

        if (nextSlot.start >= currentSlot.end) {
          break;
        }

        if (!this.slotsOverlap(currentSlot, nextSlot)) {
          continue;
        }

        this.addConflict(conflictMap, currentSlot, nextSlot);
        this.addConflict(conflictMap, nextSlot, currentSlot);
      }
    }
  }

  const resultByResource = new Map<number, ResourceSlotsDto>();
  for (const slot of slots) {
    let resource = resultByResource.get(slot.resourceId);

    if (!resource) {
      resource = {
        resourceId: slot.resourceId,
        slots: [],
      };
      resultByResource.set(slot.resourceId, resource);
    }

    resource.slots.push({
      ...slot,
      conflicts: conflictMap.get(slot.id) ?? [],
    });
  }

  return [...resultByResource.values()];
}

/**
 * Returns whether two slots overlap in time. Adjacent slots do not overlap.
 */
private slotsOverlap(
  first: Pick<Slot, 'start' | 'end'>,
  second: Pick<Slot, 'start' | 'end'>,
): boolean {
  return first.start < second.end && second.start < first.end;
}

/**
 * Appends a conflicting slot to the conflict map for the given slot.
 */
private addConflict(
  conflictMap: Map<number, SlotDto[]>,
  slot: Slot,
  conflictingSlot: Slot,
): void {
  const conflicts = conflictMap.get(slot.id) ?? [];
  conflicts.push(this.toConflictDto(conflictingSlot));
  conflictMap.set(slot.id, conflicts);
}

/**
 * Maps a slot entity to a conflict DTO without nested conflicts.
 */
private toConflictDto(slot: Slot): SlotDto {
  return {
    id: slot.id,
    name: slot.name,
    start: slot.start,
    end: slot.end,
    resourceId: slot.resourceId,
  };
}

async getSlots(): Promise<ResourceSlotsDto[]> {
  const [slots, dependencies, resources] = await Promise.all([
    this.manager.find(Slot, {
      order: { start: 'ASC', id: 'ASC' },
    }),
    this.manager.find(BlockingDependency),
    this.manager.find(Resource, {
      order: { id: 'ASC' },
    }),
  ]);

  const slotsByResource = new Map<number, Slot[]>();
  for (const slot of slots) {
    const resourceSlots = slotsByResource.get(slot.resourceId) ?? [];
    resourceSlots.push(slot);
    slotsByResource.set(slot.resourceId, resourceSlots);
  }

  const blockersByResource = new Map<number, number[]>();
  for (const dependency of dependencies) {
    const blockers = blockersByResource.get(dependency.blockedResourceId) ?? [];
    blockers.push(dependency.blockingResourceId);
    blockersByResource.set(dependency.blockedResourceId, blockers);
  }

  const conflictMap = new Map<number, SlotDto[]>();
  this.computeSameResourceConflicts(slotsByResource, conflictMap);
  this.computeBlockingConflicts(dependencies, slotsByResource, conflictMap);

  return resources.map((resource) => {
    const ownSlots = slotsByResource.get(resource.id) ?? [];
    const blockerSlots = (blockersByResource.get(resource.id) ?? []).flatMap(
      (blockerResourceId) => slotsByResource.get(blockerResourceId) ?? [],
    );
    const visibleSlots = [...ownSlots, ...blockerSlots].sort(
      (first, second) =>
        first.start.localeCompare(second.start) || first.id - second.id,
    );

    return {
      resourceId: resource.id,
      slots: visibleSlots.map((slot) => ({
        ...slot,
        conflicts: conflictMap.get(slot.id) ?? [],
      })),
    };
  });
}

/**
 * Records bidirectional conflicts between overlapping slots on the same resource.
 */
private computeSameResourceConflicts(
  slotsByResource: Map<number, Slot[]>,
  conflictMap: Map<number, SlotDto[]>,
): void {
  for (const resourceSlots of slotsByResource.values()) {
    for (let slotIndex = 0; slotIndex < resourceSlots.length; slotIndex++) {
      const currentSlot = resourceSlots[slotIndex];

      for (
        let nextIndex = slotIndex + 1;
        nextIndex < resourceSlots.length;
        nextIndex++
      ) {
        const nextSlot = resourceSlots[nextIndex];

        if (nextSlot.start >= currentSlot.end) {
          break;
        }

        if (!this.slotsOverlap(currentSlot, nextSlot)) {
          continue;
        }

        this.addConflict(conflictMap, currentSlot, nextSlot);
        this.addConflict(conflictMap, nextSlot, currentSlot);
      }
    }
  }
}

/**
 * Records one-directional conflicts from blocking resources onto blocked resources.
 */
private computeBlockingConflicts(
  dependencies: BlockingDependency[],
  slotsByResource: Map<number, Slot[]>,
  conflictMap: Map<number, SlotDto[]>,
): void {
  for (const dependency of dependencies) {
    const blockedSlots =
      slotsByResource.get(dependency.blockedResourceId) ?? [];
    const blockingSlots =
      slotsByResource.get(dependency.blockingResourceId) ?? [];

    for (const blockedSlot of blockedSlots) {
      for (const blockingSlot of blockingSlots) {
        if (blockingSlot.start >= blockedSlot.end) {
          break;
        }

        if (!this.slotsOverlap(blockedSlot, blockingSlot)) {
          continue;
        }

        this.addConflict(conflictMap, blockedSlot, blockingSlot);
      }
    }
  }
}

